-- =====================================================================
-- 레이팅 시연 데이터: 회원 24명, 2026년 10월 경기 34개(축구+풋살 15, 테니스 19)와 레이팅 이력 226행
-- 이 파일은 scripts/rating-demo-data.ps1이 만든다. 직접 고치지 말고 스크립트를 고쳐 다시 만든다.
-- 대상: 20261109-evaluation-items.sql, 20261110-seoul-public-facilities.sql, 20261111-demo-match-data.sql을 적용한 DB (로컬·운영)
-- 내용
--   * 회원 rating-01~24@spoit.test (비밀번호·역할은 demo-001@spoit.test와 같음). 마이페이지에서 배치 중과 배치 완료가 모두 보인다.
--   * 경기는 공공 체육시설에서 수동 배정(담당자)·결과 확정·레이팅 반영까지 끝난 종료 상태다.
--     27개는 두 팀장의 평가가 들어온 시점에, 7개는 평가 없이 결과 마감(종료 24시간 뒤)에 반영됐다.
--   * 이력은 RatingCalculator와 같은 식(팀 평균 → 기대 승률 → K 64/32 → Elo → 평가 보정)으로 1000부터 시간순으로 계산했다.
-- 원칙
--   * 한 트랜잭션. 사전 확인에 실패하면 멈추고 아무 행도 넣지 않는다.
--   * rating-01@spoit.test가 이미 있으면 적용된 것으로 보고 아무것도 넣지 않는다(오류 없음).
--   * 시설·종목·평가 항목·담당자는 이름으로 찾는다. 새 행 번호는 각 테이블의 현재 최대 번호 다음부터 쓴다. 기존 행은 바꾸지 않는다.
-- =====================================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 0. 이름으로 번호 찾기
SET @rs_F = (SELECT MAX(sport_id) FROM sport WHERE name = '축구+풋살');
SET @rs_T = (SELECT MAX(sport_id) FROM sport WHERE name = '테니스');
SET @rf1 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '송파구' AND f.name = '잠실종합운동장 풋살경기장' AND f.deleted_at IS NULL);
SET @rf1_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf1 AND u.email LIKE 'facility-__@spoit.test');
SET @rf2 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '마포구' AND f.name = '서울월드컵경기장 풋살구장' AND f.deleted_at IS NULL);
SET @rf2_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf2 AND u.email LIKE 'facility-__@spoit.test');
SET @rf3 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '광진구' AND f.name = '뚝섬한강공원 축구장 1' AND f.deleted_at IS NULL);
SET @rf3_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf3 AND u.email LIKE 'facility-__@spoit.test');
SET @rf4 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '동작구' AND f.name = '보라매공원 인조잔디축구장' AND f.deleted_at IS NULL);
SET @rf4_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf4 AND u.email LIKE 'facility-__@spoit.test');
SET @rf5 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '용산구' AND f.name = '한남테니스장' AND f.deleted_at IS NULL);
SET @rf5_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf5 AND u.email LIKE 'facility-__@spoit.test');
SET @rf6 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '서초구' AND f.name = '잠원한강테니스장' AND f.deleted_at IS NULL);
SET @rf6_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf6 AND u.email LIKE 'facility-__@spoit.test');
SET @rf7 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '마포구' AND f.name = '월드컵공원 테니스장' AND f.deleted_at IS NULL);
SET @rf7_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf7 AND u.email LIKE 'facility-__@spoit.test');
SET @rf8 = (SELECT MAX(f.facility_id) FROM facility f JOIN region r ON r.region_id = f.region_id AND r.parent_region_id = 1 WHERE r.name = '중구' AND f.name = '장충테니스장' AND f.deleted_at IS NULL);
SET @rf8_mgr = (SELECT MIN(fm.user_id) FROM facility_manager fm JOIN app_user u ON u.user_id = fm.user_id WHERE fm.facility_id = @rf8 AND u.email LIKE 'facility-__@spoit.test');
SET @rr_광진구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '광진구');
SET @rr_동작구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '동작구');
SET @rr_마포구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '마포구');
SET @rr_서초구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '서초구');
SET @rr_송파구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '송파구');
SET @rr_용산구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '용산구');
SET @rr_중구 = (SELECT MAX(region_id) FROM region WHERE parent_region_id = 1 AND name = '중구');
SET @ri_F_0 = (SELECT MAX(item_id) FROM sport_evaluation_item WHERE item_code = 'SOCCER_TECH' AND is_active = TRUE AND sport_id = @rs_F);
SET @ri_F_1 = (SELECT MAX(item_id) FROM sport_evaluation_item WHERE item_code = 'FUTSAL_PASS' AND is_active = TRUE AND sport_id = @rs_F);
SET @ri_F_2 = (SELECT MAX(item_id) FROM sport_evaluation_item WHERE item_code = 'FUTSAL_POSITION' AND is_active = TRUE AND sport_id = @rs_F);
SET @ri_T_0 = (SELECT MAX(item_id) FROM sport_evaluation_item WHERE item_code = 'TENNIS_SERVE' AND is_active = TRUE AND sport_id = @rs_T);
SET @ri_T_1 = (SELECT MAX(item_id) FROM sport_evaluation_item WHERE item_code = 'TENNIS_RALLY' AND is_active = TRUE AND sport_id = @rs_T);
SET @ri_T_2 = (SELECT MAX(item_id) FROM sport_evaluation_item WHERE item_code = 'TENNIS_POSITION' AND is_active = TRUE AND sport_id = @rs_T);
SELECT MAX(password_hash), MAX(role) INTO @rating_hash, @rating_role FROM app_user WHERE email = 'demo-001@spoit.test';

-- 사전 확인. 출력되는 값이 모두 1이어야 진행한다. already_applied가 1이면 이미 적용된 DB라 아무것도 넣지 않는다.
SELECT (@rs_F IS NOT NULL AND @rs_T IS NOT NULL), ((@rf1 IS NOT NULL AND @rf1_mgr IS NOT NULL) + (@rf2 IS NOT NULL AND @rf2_mgr IS NOT NULL) + (@rf3 IS NOT NULL AND @rf3_mgr IS NOT NULL) + (@rf4 IS NOT NULL AND @rf4_mgr IS NOT NULL) + (@rf5 IS NOT NULL AND @rf5_mgr IS NOT NULL) + (@rf6 IS NOT NULL AND @rf6_mgr IS NOT NULL) + (@rf7 IS NOT NULL AND @rf7_mgr IS NOT NULL) + (@rf8 IS NOT NULL AND @rf8_mgr IS NOT NULL)) = 8, ((@rr_광진구 IS NOT NULL) + (@rr_동작구 IS NOT NULL) + (@rr_마포구 IS NOT NULL) + (@rr_서초구 IS NOT NULL) + (@rr_송파구 IS NOT NULL) + (@rr_용산구 IS NOT NULL) + (@rr_중구 IS NOT NULL)) = 7, ((@ri_F_0 IS NOT NULL) + (@ri_F_1 IS NOT NULL) + (@ri_F_2 IS NOT NULL) + (@ri_T_0 IS NOT NULL) + (@ri_T_1 IS NOT NULL) + (@ri_T_2 IS NOT NULL)) = 6,
       @rating_hash IS NOT NULL,
       NOT EXISTS (SELECT 1 FROM match_application WHERE receipt_no IN ('RCPT-20260926-BCBN4C5E', 'RCPT-20260926-3STLZNUK', 'RCPT-20260926-BX4A58DD', 'RCPT-20260927-9W6L2RCA', 'RCPT-20260926-EUAGS5W2', 'RCPT-20260926-HEK2UTUV', 'RCPT-20260926-2DWW83XC', 'RCPT-20260926-97NGGTNL', 'RCPT-20260927-PSFFNN2G', 'RCPT-20260927-BB2ZXLTP', 'RCPT-20260929-BKTX5PCM', 'RCPT-20260929-67HVQQUX', 'RCPT-20260929-Z8LBMNHN', 'RCPT-20260929-LPV7A8PW', 'RCPT-20260926-N8E79ZRA', 'RCPT-20260927-Q4JQFF2V', 'RCPT-20260927-RD9Z9RCX', 'RCPT-20260928-CELP4FL7', 'RCPT-20260927-SUGRKWYA', 'RCPT-20261002-QLVSD2HF', 'RCPT-20261002-X9P79YX7', 'RCPT-20261002-6R54NCFK', 'RCPT-20261002-SM8V9KK4', 'RCPT-20261002-N8JW5UTK', 'RCPT-20261002-7F24ZP84', 'RCPT-20261002-6JU435WN', 'RCPT-20261002-FLA23WGN', 'RCPT-20261002-XVSAPABL', 'RCPT-20260927-8T7GKLUD', 'RCPT-20261002-NDYYYRAT', 'RCPT-20261002-L6RTT2SK', 'RCPT-20261002-9NED68N6', 'RCPT-20261002-HJ6J8PC4', 'RCPT-20261002-26NX7RXG', 'RCPT-20261003-U8XTSR2F', 'RCPT-20261003-BVH7GQGP', 'RCPT-20261002-Z4RPV2V6', 'RCPT-20261004-3X3WN4MR', 'RCPT-20261004-Y8T7K5MZ', 'RCPT-20261004-SYGLFEWK', 'RCPT-20261003-Y88DAJU3', 'RCPT-20261004-M2Z5XD3H', 'RCPT-20261004-H2HH7KE5', 'RCPT-20261004-QZ66UKZX', 'RCPT-20261002-BS8P5JQP', 'RCPT-20261003-NZUSDSBN', 'RCPT-20261003-79CP7NNP', 'RCPT-20261003-4DWJMXHB', 'RCPT-20261004-BC3FEMN9', 'RCPT-20261003-K35FYVZ8', 'RCPT-20261004-YS9UGKZW', 'RCPT-20261004-DTU2VFCY', 'RCPT-20261004-SSRBY5JT', 'RCPT-20261004-VCEETGYG', 'RCPT-20261004-MYU5YW42', 'RCPT-20261004-LECU2WMD', 'RCPT-20261004-YEXFEYH4', 'RCPT-20261004-HP9DEVC6', 'RCPT-20261004-5NN7VG95', 'RCPT-20261004-XYYT3X39', 'RCPT-20261004-YAPPTSCW', 'RCPT-20261004-Q2VKWZVZ', 'RCPT-20261004-CFZNHQSS', 'RCPT-20261005-E3RP9XAT', 'RCPT-20261004-WANEFXML', 'RCPT-20261004-KZQ4UYG8', 'RCPT-20261004-D9RW8NZJ', 'RCPT-20261004-S7JZBWX3', 'RCPT-20261004-ZCXWLRTN', 'RCPT-20261004-4NCRAX7Q', 'RCPT-20261004-VSK9GNUH', 'RCPT-20261004-JEWJNVKW', 'RCPT-20261004-CXDSBUWW', 'RCPT-20261005-QD4UKJH4', 'RCP